// Deterministic retry-eligibility gate. This decides whether a job
// gets another attempt - it never depends on AI judgment and must
// always converge (attemptCount can only go up, never reset silently).
const item = $input.first().json;

const isRetryableErrorCode = !(item.nonRetryableErrorCodes || []).includes(item.errorCode);
const withinAttemptBudget = Number(item.attemptCount) < Number(item.maxRetryAttempts);
const retryEligible = isRetryableErrorCode && withinAttemptBudget;

let ineligibleReason = null;
if (!isRetryableErrorCode) ineligibleReason = `Error code '${item.errorCode}' is configured as non-retryable.`;
else if (!withinAttemptBudget) ineligibleReason = `Attempt count ${item.attemptCount} has reached the max of ${item.maxRetryAttempts}.`;

const nextAttemptNumber = Number(item.attemptCount) + 1;
const rawDelay = Number(item.backoffBaseSeconds) * Math.pow(Number(item.backoffMultiplier), Number(item.attemptCount));
const backoffDelaySeconds = Math.min(rawDelay, Number(item.backoffMaxSeconds));

return [{
  json: {
    ...item,
    retryEligible,
    ineligibleReason,
    nextAttemptNumber,
    backoffDelaySeconds
  }
}];

