const state = $('Check Retry Eligibility').first().json;
const response = $input.first().json;

const retrySucceeded = !(response.error) && (response.statusCode === undefined || (response.statusCode >= 200 && response.statusCode < 300));

return [{
  json: {
    ...state,
    retrySucceeded,
    lastResponseSnippet: JSON.stringify(response).slice(0, 500),
    attemptCount: state.nextAttemptNumber
  }
}];
